mapper.select:
SELECT staff_no as "staffNo", staff_name as "staffName", organization_code as "organizationCode", position_name as "positionName", employment_status as "employmentStatus", duty_name as "dutyName", retirement_date as "retirementDate", last_synced_at as "lastSyncedAt"
FROM korus_staff_snapshot

  use_yn='Y'
  AND staff_no = #{staffNo}
  AND staff_name LIKE CONCAT('%', #{staffName}, '%')
  AND organization_code = #{organizationCode}

SELECT u.user_id as "userId", k.staff_no as "staffNo", k.staff_name as "staffName", k.organization_code as "organizationCode", o.organization_name as "organizationName", k.position_name as "positionName", k.employment_status as "employmentStatus", k.duty_name as "dutyName", k.retirement_date as "retirementDate", k.last_synced_at as "lastSyncedAt", u.system_use_yn as "systemUseYn"
FROM user_account u JOIN korus_staff_snapshot k ON k.staff_no=u.staff_no JOIN organization o ON o.organization_code=k.organization_code

  u.use_yn='Y'
  AND u.user_id = #{userId}
  AND k.staff_no = #{staffNo}
  AND k.staff_name LIKE CONCAT('%', #{staffName}, '%')
  AND k.organization_code = #{organizationCode}
  AND k.position_name LIKE CONCAT('%', #{positionName}, '%')
  AND k.employment_status = #{employmentStatus}
  AND u.system_use_yn = #{systemUseYn}
  AND EXISTS (SELECT 1 FROM user_role ur WHERE ur.user_id=u.user_id AND ur.role_code=#{roleCode} AND ur.use_yn='Y')
  AND (k.staff_name LIKE CONCAT('%', #{filter}, '%') OR k.staff_no LIKE CONCAT('%', #{filter}, '%'))

ORDER BY k.staff_no

SELECT organization_code as "organizationCode", organization_name as "organizationName", organization_type as "organizationType", parent_organization_code as "parentOrganizationCode", effective_start_date as "effectiveStartDate", effective_end_date as "effectiveEndDate", relation_change_reason as "relationChangeReason", use_yn as "useYn"
FROM organization

  1=1
  AND organization_code = #{organizationCode}
  AND organization_name LIKE CONCAT('%', #{organizationName}, '%')
  AND organization_type = #{organizationType}
  AND use_yn = #{useYn}
  AND (organization_code LIKE CONCAT('%', #{filter}, '%') OR organization_name LIKE CONCAT('%', #{filter}, '%'))

ORDER BY organization_code
